/// `(pool, token0, token1)` for a selector and pool index.
pub fn lookup(selector: [u8; 4], index: u16) -> Option<(Address, Address, Address)> {
    TABLE
        .iter()
        .find(|r| r.0 == selector && r.1 == index)
        .map(|r| (r.2, r.3, r.4))
}
